{
    public interface IPatchDownloadService
    {
        /// <summary>
        /// Lê o patch.lua (sem dependência de Entities). Retorna um enum ou lista vazia.
        /// </summary>
        Task<IReadOnlyCollection<UpdateItem>> GetPatchesAsync();

        /// <summary>
        /// Baixa um único update. `startIndex` e `latestIndex` permitem que o
        /// serviço “abra” o download em qualquer ponto (reconexão).
        /// </summary>
